// Package: AWSSDK.CognitoIdentityProvider
using Amazon.CognitoIdentityProvider;
using Amazon.CognitoIdentityProvider.Model;

var cognitoClient = new AmazonCognitoIdentityProviderClient(RegionEndpoint.USEast1);
string clientId = "4k2hj98a2vbiqg7g3g4r5t6y";

var signUpRequest = new SignUpRequest
{
    ClientId = clientId,
    Username = "alice@example.com",
    Password = "SecureP@ssw0rd!",
    SecretHash = ComputeSecretHash("alice@example.com", clientId, "app-client-secret")
};

var signUpResponse = await cognitoClient.SignUpAsync(signUpRequest);
Console.WriteLine($"User confirmed: {signUpResponse.UserConfirmed}");
Console.WriteLine($"UserSub: {signUpResponse.UserSub}");

var authRequest = new AdminInitiateAuthRequest
{
    UserPoolId = "us-east-1_Abc123XYZ",
    ClientId = clientId,
    AuthFlow = AuthFlowType.ADMIN_NO_SRP_AUTH,
    AuthParameters = new Dictionary<string, string>
    {
        ["USERNAME"] = "alice@example.com",
        ["PASSWORD"] = "SecureP@ssw0rd!"
    }
};

var authResponse = await cognitoClient.AdminInitiateAuthAsync(authRequest);
string idToken = authResponse.AuthenticationResult.IdToken;
string accessToken = authResponse.AuthenticationResult.AccessToken;

Console.WriteLine($"ID Token: {idToken}");
